262	
263	  function showSummary() {
264	    const summary = document.getElementById('summary');
265	    const pct = Math.round(right/total*100);
266	    document.getElementById('sum-score').textContent = `${right}/${total}（${pct}%）`;
267	    let fb = '', cls = 'good';
268	    if (pct >= 85) {
269	      fb = '<strong>掌握扎实</strong>——环节边界清晰，场景判断到位。M1 地基 + M2 数据侧这块稳了，可以推进 L05 Embedding 选型。注意错题（如果有），重看下反馈里的「为什么不是其他选项」即可。';
270	      cls = 'good';
271	    } else if (pct >= 60) {
272	      fb = '<strong>基础概念掌握，但场景判断还有盲点</strong>。重点回看错题涉及的环节：<br>• 切分 vs 向量化 vs 检索的边界 → 重看 [[Q&A 0001 环节边界口诀]] 和 L02 排查练习<br>• 切分 vs 元数据的职责 → 重看 L03/L04<br>• Recall/Precision 优化方向 → 重看 Q&A 0002<br>建议把错题对应的课程「运维场景代入」和「面试视角」再过一遍，然后进 L05。';
273	      cls = 'mid';
274	    } else if (pct >= 35) {
275	      fb = '<strong>概念有印象，但跨环节判断弱</strong>。这说明「文字看懂」和「会判断」之间还有距离（fluency illusion）。建议：①重看 L02 全流程地图的 9 环节职责表和木桶效应；②做一遍 L02 排查练习（6 题场景诊断）；③回头再做本测验。别急着进 L05，先把这块的判断力练出来。';
276	      cls = 'low';
277	    } else {
278	      fb = '<strong>建议先重看 L01–L04 课程正文</strong>。别急着推进——地基不稳后面会更吃力。重看时重点抓：RAG 为什么需要（L01）、9 环节各自职责（L02）、切分策略表（L03）、元数据过滤（L04）。看完再做本测验，目标至少 60% 再进 L05。';
279	      cls = 'low';
280	    }
281	    document.getElementById('sum-feedback').innerHTML = fb;
282	    summary.classList.add('show', cls);
283	    summary.scrollIntoView({behavior:'smooth', block:'center'});
284	  }
