288	    const fb = quiz.querySelector('.quiz-feedback');
289	    let answered = false;
290	    opts.forEach(opt => {
291	      opt.addEventListener('click', () => {
292	        if (answered) return;
293	        answered = true;
294	        const isCorrect = opt.dataset.correct === 'true';
295	        opts.forEach(o => {
