251	<script>
252	  let done = 0, right = 0;
253	  const total = 8;
254	  const quizzes = document.querySelectorAll('.quiz');
255	
256	  function updateProgress() {
257	    document.getElementById('q-progress').textContent = `${done}/${total}`;
258	    document.getElementById('q-bar').style.width = `${done/total*100}%`;
259	    if (done === total) showSummary();
260	  }
261	
262	  function showSummary() {
263	    const summary = document.getElementById('summary');
264	    const pct = Math.round(right/total*100);
265	    document.getElementById('sum-score').textContent = `${right}/${total}（${pct}%）`;
266	    let fb = '', cls = 'good';
267	    if (pct >= 85) {
268	      fb = '<strong>检索侧三件套掌握扎实</strong>——embedding / 混合 / rerank 职责清晰，场景诊断到位，rerank 的"窄窗口 recall=precision"和"recall@K1 天花板"这两条核心都吃透了。M3 检索侧稳了，可以进 L08 上下文组装与 Prompt 工程（M4 生成侧）。';
269	      cls = 'good';
270	    } else if (pct >= 60) {
271	      fb = '<strong>检索侧概念掌握，但 rerank / 诊断还有盲点</strong>。重点回看错题：<br>• rerank 提什么、recall@K1 天花板 → 重看 <a href="../lessons/0007-rerank.html">L07</a>「68%→89% 真相」和「关键前提」<br>• 诊断该加什么（recall 够 vs 不够） → 重看 L07「运维实战」表 + Q&A 0002<br>• K1/K2 含义 → 重看 L07「Top-K 怎么定」<br>把错题反馈里的"为什么不是其他选项"过一遍，再进 L08。';
272	      cls = 'mid';
273	    } else if (pct >= 35) {
274	      fb = '<strong>检索侧概念有印象，但跨环节判断弱</strong>。建议：①重看 <a href="../lessons/0007-rerank.html">L07</a> 正文（尤其两阶段、bi vs cross、68%→89% 真相三节）；②配合 <a href="quiz-midterm.html">期中 Q9–Q16</a> 一起复习检索侧；③回头再做本测验。别急着进 L08，先把检索侧判断力练出来。';
275	      cls = 'low';
276	    } else {
277	      fb = '<strong>建议先重看 L05–L07 课程正文</strong>。检索侧是 RAG 命中的关键，地基不稳后面生成侧会更吃力。重看重点：L05 embedding 选型与维度、L06 混合检索 RRF、L07 两阶段与 rerank 天花板。配合 <code>reference/hnsw-cheatsheet.md</code> 速查。看完目标至少 60% 再进 L08。';
278	      cls = 'low';
279	    }
280	    document.getElementById('sum-feedback').innerHTML = fb;
281	    summary.classList.add('show', cls);
282	    summary.scrollIntoView({behavior:'smooth', block:'center'});
283	  }
284	
285	  quizzes.forEach(quiz => {
286	    const opts = quiz.querySelectorAll('.quiz-opt');
287	    const fb = quiz.querySelector('.quiz-feedback');
288	    let answered = false;
289	    opts.forEach(opt => {
290	      opt.addEventListener('click', () => {
291	        if (answered) return;
292	        answered = true;
293	        const isCorrect = opt.dataset.correct === 'true';
294	        opts.forEach(o => {
295	          o.classList.remove('correct','wrong');
296	          o.classList.add('reveal');
297	          if (o.dataset.correct === 'true') o.classList.add('correct');
298	          else if (o === opt) o.classList.add('wrong');
299	        });
300	        fb.classList.add('show');
301	        done++; if (isCorrect) right++;
302	        updateProgress();
303	      });
304	    });
305	  });
